pub const Binding = struct {
    /// The name `starlancer.ini` keys its bindings by.
    name: []const u8,
    /// The language string of the name the controls screens show.
    string: u16,
    /// A DirectInput scan code (`DIK_*`).
    key: u16,
    modifier: Modifier,
    /// A joystick button, or null for none.
    button: ?u8,
};

