test binding {
    for (std.enums.values(Action)) |action| {
        const name = binding(action).name;
        const tag = @tagName(action);
        try std.testing.expectEqual(name.len, tag.len);
        for (name, tag) |c, t| {
            try std.testing.expectEqual(if (c == ' ' or c == '-') '_' else std.ascii.toLower(c), t);
        }
    }
}
